<template>
  <div class="modelbig">
    <div class="serch">
      <el-form class="demo-ruleForm">
        <!-- <el-form-item label="模型类型" label-width="80px">
          <el-select v-model="queryParams.model_type" placeholder="请选择模型类型" size="small" clearable filterable style="width: 90%" @change="axioss()">
            <el-option v-for="item in modelTypeDict" :key="item.data_value+item.data_label" :label="item.data_label" :value="item.data_value"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="大类类型" label-width="80px">
          <el-select v-model="queryParams.model_template_config_type_id" placeholder="请选择模型类型" size="small" clearable filterable style="width: 90%" @change="axioss()">
            <el-option v-for="item in modelTypeOptions" :key="'查询'+item.id+item.model_type_name" :label="item.model_type_name" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button icon="el-icon-search" type="primary" size="small" @click="axioss">搜索</el-button>
        </el-form-item> -->
        <el-form-item>
          <el-button icon="el-icon-plus" type="primary" size="small" @click=handleAddDialog>新增</el-button>
        </el-form-item>
      </el-form>
    </div>
    <div class="table">
      <div class="jia_table">
        <el-table :data="tableData" style="width: 100%" :header-cell-style="{ background: '#f9fbff',height:'48.5px',fontSize:'14px' }" height="95%">
          <!-- <el-table-column prop="id" label="ID" width="180"></el-table-column> -->
          <el-table-column prop="index" label="序号" width="100px">
            <template slot-scope="scope">
              {{ scope.$index + 1 }}
            </template>
          </el-table-column>
          <el-table-column prop="model_type_name" label="模型类型名称" width="200px"></el-table-column>
          <el-table-column prop="model_type_content" label="内容描述"></el-table-column>
          <!-- <el-table-column prop="created_at" label="创建时间"></el-table-column>
          <el-table-column prop="updated_at" label="更新时间"></el-table-column> -->
          <el-table-column label="操作" width="200" align="center">
            <template slot-scope="scope">
              <el-button size="mini" type="text" icon="el-icon-edit" @click="handleEdit(scope.row)">编辑</el-button>
              <el-button size="mini" type="text" icon="el-icon-delete" @click="handleDelete(scope.row)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
      </div>
      <div class="page">
        <el-pagination @current-change="axioss" @size-change="axioss" :current-page="queryParams.page" :page-size="queryParams.per_page" :page-sizes="pagesizes" background layout="total, prev, pager, next, jumper,sizes" :total="total">
        </el-pagination>
      </div>
    </div>
    <!-- 新增、修改弹窗 -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="530px">
      <el-form :model="formData" ref="formData" :rules="rules" label-width="80px" class="roleForm" label-position="top">
        <el-form-item label="模型类型名称" prop="model_name">
          <el-input v-model="formData.model_type_name" autocomplete="off" placeholder="请输入模型类型"></el-input>
        </el-form-item>
        <el-form-item label="内容描述" prop="model_type_content">
          <el-input v-model="formData.model_type_content" autocomplete="off" placeholder="请输入内容描述" type="textarea"></el-input>
        </el-form-item>
        <!-- <el-form-item label="模型类型" prop="model_type">
          <el-select v-model="formData.model_type" placeholder="请选择模型类型" clearable filterable style="width: 100%" @change="axioss()">
            <el-option v-for="item in modelTypeDict" :key="item.data_value+item.data_label" :label="item.data_label" :value="item.data_value"> </el-option>
          </el-select>
        </el-form-item> -->
      </el-form>

      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取 消</el-button>
        <el-button type="primary" @click="handleSubmit">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>
  
  <script>
import { modelApi } from '@/api/model';
export default {
  data() {
    return {
      tableData: [
        //   {
        //     id: 1,
        //     model_type_name: "物体检测",
        //     model_type_content: "物体检测",
        //     created_at: "Wed, 25 Dec 2024 08:53:08 GMT",
        //     updated_at: "Wed, 25 Dec 2024 08:53:08 GMT"
        //   },
        //   {
        //     id: 2,
        //     model_type_name: "串行",
        //     model_type_content: "串行",
        //     created_at: "Wed, 25 Dec 2024 08:53:08 GMT",
        //     updated_at: "Wed, 25 Dec 2024 08:53:08 GMT"
        //   },
        //   {
        //     id: 3,
        //     model_type_name: "统计类",
        //     model_type_content: "统计类",
        //     created_at: "Wed, 25 Dec 2024 08:53:08 GMT",
        //     updated_at: "Wed, 25 Dec 2024 08:53:08 GMT"
        //   }
      ],
      queryParams: {
        page: 1,
        per_page: 15,
      },
      total: 0,
      pagesizes: [15, 35, 50, 100, 150, 200, 300],
      dialogVisible: false,
      dialogTitle: '',
      formData: {
        model_type_name: '',
        model_type_content: '',
      },
      rules: {},
      config: {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      }
    };
  },
  created() {
    this.axioss();
  },
  mounted() {

  },
  methods: {
    axioss() {
      this.$http.get(modelApi.getModelType, {
        params: this.queryParams
      }).then(response => {
        this.tableData = response.data.data.data
        this.total = response.data.data.pagination.total_items
      }).catch(rek => {
        console.log(rek)
      })
    },
    // 新增按钮
    handleAddDialog() {
      this.dialogVisible = true
      this.dialogTitle = "新增模型"
      this.formData = {
        model_type_name: '',
        model_type_content: '',
      }
    },
    // 修改按钮
    handleEdit(row) {
      this.$http.get(modelApi.gteModelTypeOne, {
        params: {
          id: row.id
        }
      }).then(response => {
        if (response.data.code == 200) {
          this.formData = response.data.data
          this.dialogVisible = true
          this.dialogTitle = "修改模型"
        }
      }).catch(rek => {
        console.log(rek)
      })
    },
    // 删除按钮
    handleDelete(row) {
      this.$confirm('是否确认删除当前数据？').then(() => {
        let msg = {
          id: row.id
        }
        let formData = new FormData();
        // 遍历 msg 对象，并将键值对添加到 formData 中
        Object.keys(msg).forEach(key => {
          formData.append(key, msg[key]);
        });
        this.$http.post(modelApi.deleteModelType, msg, this.config)
          .then(response => {
            if (response.data.code == 200) {
              this.$message({
                type: 'success',
                message: response.data.msg
              })
              this.axioss();
            }
          })
      }).then(() => {
        
      }).catch(() => {
        this.$message(
          {
            type: 'info',
            message: '取消删除'
          }
        )
      });
    },
    // 新增、修改确定按钮
    handleSubmit() {
      let httpUrl
      if (this.dialogTitle == '新增模型') {
        httpUrl = modelApi.addModelType
      } else {
        httpUrl = modelApi.updateModelType
      }
      let formData = new FormData();
      // 遍历 msg 对象，并将键值对添加到 formData 中
      Object.keys(this.formData).forEach(key => {
        formData.append(key, this.formData[key]);
      });
      this.$http.post(httpUrl, formData, this.config)
        .then(response => {
          if (response.data.code == 200) {
            this.$message({
              type: 'success',
              message: response.data.msg
            })
            this.dialogVisible=false
            this.axioss();
          }
        })
        .catch(rek => {
          console.log(rek)
        })
    }
  }
};
  </script>
  
  <style lang="scss" scoped>
.modelbig {
  width: 100%;
  height: 100%;
  background-color: #ffffff;
  border-radius: 6px;
  .serch {
    height: 70px;
    // padding-top: 16px;
    // padding-bottom: 16px;
    padding: 16px 18px;
    box-sizing: border-box;
    position: relative;
    .demo-ruleForm {
      height: 100%;
      display: flex;
      justify-content: left;
      align-items: flex-start;
      flex-wrap: wrap;
    }
  }
  .table {
    height: 87%;
    position: relative;
    .jia_table {
      height: 100%;
      .el-table {
        height: 100%;
        background-image: url("../../img/home/placeholder_bottom.png");
        background-position: bottom;
        background-size: 100% 60%;
        background-repeat: no-repeat;
      }
      ::v-deep .el-table--border .el-table__cell,
      .el-table__body-wrapper .el-table--border.is-scrolling-left ~ .el-table__fixed {
        border-right: none;
      }
      ::v-deep .el-table__empty-block {
        // display: none !important;
        .el-table__empty-text {
          color: transparent;
        }
      }
      ::v-deep .el-empty {
        width: 307px;
        height: 353px;
        position: absolute;
        top: 50%;
        left: 50%;
        margin-left: -153px;
        margin-top: -176px;
        .el-empty__image img {
          vertical-align: top;
          height: 147%;
          width: 100%;
        }
        .el-empty__description {
          margin-top: 20px;
          margin-right: 70px;
        }
      }
    }
    .page {
      width: 100%;
      height: 33px;
      // background-color: pink;
      text-align: right;
      position: absolute;
      right: 0;
      bottom: -24px;
    }
  }
}
</style>